struct HostHandleCloser {
    void operator()(HANDLE handle) const noexcept {
        if (handle != nullptr && handle != INVALID_HANDLE_VALUE) (void)CloseHandle(handle);
    }
};
struct DeviceInfoListCloser {
    void operator()(HDEVINFO devices) const noexcept {
        if (devices != nullptr && devices != INVALID_HANDLE_VALUE) {
            (void)SetupDiDestroyDeviceInfoList(devices);
        }
    }
};
using ScopedHostHandle = std::unique_ptr<void, HostHandleCloser>;
using ScopedDeviceInfoList = std::unique_ptr<void, DeviceInfoListCloser>;

#if defined(GALAXY_NATIVE_HOST_TEST_SUPPORT)
// Fault points are confined to the test-support build and its calling thread.
using NativeHostOwnershipTestHook = bool (*)(
    unsigned, const std::filesystem::path&, unsigned);
thread_local NativeHostOwnershipTestHook s_host_ownership_test_hook{};
bool host_ownership_test_point(unsigned phase,
    const std::filesystem::path& path, unsigned index = 0u) {
    return s_host_ownership_test_hook != nullptr &&
        s_host_ownership_test_hook(phase, path, index);
}
#endif

NativeIosClockSample sample_native_ios_clock() noexcept {
    const auto now_ns = []() noexcept {
        return static_cast<std::uint64_t>(std::chrono::duration_cast<
            std::chrono::nanoseconds>(
                std::chrono::steady_clock::now().time_since_epoch()).count());
    };
    NativeIosClockSample sample{};
    sample.before_ns = now_ns();
    FILETIME created{}, exited{}, kernel{}, user{};
    sample.cpu_valid = GetThreadTimes(
        GetCurrentThread(), &created, &exited, &kernel, &user) != FALSE;
    if (sample.cpu_valid) {
        sample.cpu_100ns =
            (static_cast<std::uint64_t>(kernel.dwHighDateTime) << 32u) +
            kernel.dwLowDateTime +
            (static_cast<std::uint64_t>(user.dwHighDateTime) << 32u) +
            user.dwLowDateTime;
    }
    ULONG64 cycles{};
    sample.cycles_valid =
        QueryThreadCycleTime(GetCurrentThread(), &cycles) != FALSE;
    sample.cycles = cycles;
    sample.after_ns = now_ns();
    return sample;
}

void dump_native_ios_anomalies(const NativeIosAnomalyLedger& ledger) {
    std::ostringstream output;
    std::size_t slot = 0u;
    for (const auto& record : ledger.records()) {
        const auto& id = record.identity;
        output << "[ios-anomaly] schema=1 slot=" << slot++
               << " sequence=" << record.sequence
               << " request=" << id.request << " command=" << id.command
               << " handle=" << id.handle
               << " device=" << static_cast<unsigned>(id.device)
               << " arguments-valid=" << id.arguments_valid;
        for (std::size_t i = 0; i < id.arguments.size(); ++i) {
            output << " arg" << i << '=' << id.arguments[i];
        }
        const auto sample = [&](const char* label, const NativeIosClockSample& s) {
            output << ' ' << label << "-before-ns=" << s.before_ns
                   << ' ' << label << "-after-ns=" << s.after_ns
                   << ' ' << label << "-cpu-100ns=" << s.cpu_100ns
                   << ' ' << label << "-cpu-valid=" << s.cpu_valid
                   << ' ' << label << "-cycles=" << s.cycles
                   << ' ' << label << "-cycles-valid=" << s.cycles_valid;
        };
        sample("entry", record.entry);
        sample("exit", record.exit);
        output << " wall-valid=" << record.wall_valid()
               << " minimum-elapsed-ns=" << record.minimum_elapsed_ns()
               << " maximum-elapsed-ns=" << record.maximum_elapsed_ns()
               << " unwound=" << record.unwound << '\n';
    }
    output << "[ios-anomaly-summary] schema=1 terminal=1"
           << " scope=synchronous-request-after-identity-before-handler"
           << " clock=steady-ns-with-bracketed-thread-counters"
           << " cpu-zero-delta=possibly-quantized"
           << " identity=request-entry-not-input-service-pc"
           << " device-map=0unknown,1nand,2fs,3es,4di,5bluetooth,6stm-immediate,7stm-eventhook,8other"
           << " threshold-ns=" << ledger.kThresholdNs
           << " threshold=maximum-bracketed-elapsed-ge"
           << " capacity=" << ledger.kCapacity
           << " started=" << ledger.started()
           << " finished=" << ledger.finished()
           << " slow=" << ledger.slow()
           << " retained=" << ledger.records().size()
           << " overflow=" << ledger.overflow()
           << " invalid-wall=" << ledger.invalid_wall()
           << " unwound=" << ledger.unwound() << '\n';
    std::osyncstream(std::cout) << output.str();
}

