enum class SysconfEntryType : std::uint8_t {
    BigArray = 1,
    SmallArray = 2,
    Byte = 3,
    Short = 4,
    Long = 5,
    LongLong = 6,
    ByteBool = 7,
};

struct SysconfEntry {
    SysconfEntryType type;
    std::string_view name;
    std::vector<std::byte> bytes;
};

void write_be16(std::vector<std::byte>& bytes, std::size_t offset,
                std::uint16_t value) {
    bytes[offset + 0] = static_cast<std::byte>(value >> 8);
    bytes[offset + 1] = static_cast<std::byte>(value & 0xFFu);
}

void write_be32(std::vector<std::byte>& bytes, std::size_t offset,
                std::uint32_t value) {
    bytes[offset + 0] = static_cast<std::byte>(value >> 24);
    bytes[offset + 1] = static_cast<std::byte>((value >> 16) & 0xFFu);
    bytes[offset + 2] = static_cast<std::byte>((value >> 8) & 0xFFu);
    bytes[offset + 3] = static_cast<std::byte>(value & 0xFFu);
}

void append_be16(std::vector<std::byte>& bytes, std::uint16_t value) {
    bytes.push_back(static_cast<std::byte>(value >> 8));
    bytes.push_back(static_cast<std::byte>(value & 0xFFu));
}

void append_be32(std::vector<std::byte>& bytes, std::uint32_t value) {
    bytes.push_back(static_cast<std::byte>(value >> 24));
    bytes.push_back(static_cast<std::byte>((value >> 16) & 0xFFu));
    bytes.push_back(static_cast<std::byte>((value >> 8) & 0xFFu));
    bytes.push_back(static_cast<std::byte>(value & 0xFFu));
}

std::uint16_t rfl_crc(std::span<const std::byte> bytes) {
    std::uint16_t crc = 0;
    for (const std::byte byte : bytes) {
        std::uint8_t data = static_cast<std::uint8_t>(byte);
        for (int bit = 0; bit < 8; ++bit, data <<= 1) {
            if ((crc & 0x8000u) != 0) {
                crc = static_cast<std::uint16_t>((crc << 1) ^ 0x1021u);
            } else {
                crc = static_cast<std::uint16_t>(crc << 1);
            }
            if ((data & 0x80u) != 0) {
                crc = static_cast<std::uint16_t>(crc ^ 0x0001u);
            }
        }
    }
    return crc;
}

std::vector<std::byte> be32_bytes(std::uint32_t value) {
    std::vector<std::byte> bytes;
    bytes.reserve(4);
    append_be32(bytes, value);
    return bytes;
}

std::vector<std::byte> utf16be_console_name(std::string_view ascii) {
    std::vector<std::byte> bytes(22, std::byte{0});
    const std::size_t chars = std::min<std::size_t>(ascii.size(), 10u);
    for (std::size_t i = 0; i < chars; ++i) {
        write_be16(
            bytes,
            i * 2u,
            static_cast<std::uint8_t>(ascii[i]));
    }
    bytes[21] = static_cast<std::byte>(chars);
    return bytes;
}

// Synthetic inbound Wiimote identity. BD_ADDRs are little-endian in HCI packets
// (LSB first), while WUD/SYSCONF store the Broadcom stack's internal order.
// The BTE Return_Link_Keys path rewrites the event payload in-place into that
// internal order before WUD compares it against BT.DINF.
constexpr std::array<std::uint8_t, 6> kWiimoteBdAddr{
    0x11, 0x02, 0x19, 0x79, 0x00, 0x00};
constexpr std::size_t kMaxVirtualWiimoteCount = 5;
constexpr std::array<std::uint8_t, 6> kLocalBtBdAddr{
    0x11, 0x02, 0x19, 0x79, 0x00, 0xFF};
constexpr std::array<std::uint8_t, 3> kWiimoteClassOfDevice{
    0x04, 0x25, 0x00};
constexpr std::array<std::uint8_t, 8> kWiimoteRemoteFeatures{
    0xBC, 0x02, 0x04, 0x38, 0x08, 0x00, 0x00, 0x00};
constexpr std::uint8_t kWiimoteLmpVersion = 0x02;
constexpr std::uint16_t kWiimoteManufacturerId = 0x000F;
constexpr std::uint16_t kWiimoteLmpSubversion = 0x0229;
constexpr std::uint16_t kWiimoteClockOffset = 0x8AA5;
// RMGE01's generated WPAD input decoder owns one channel-control pointer per
// remote at this table. The live Nunchuk key tables are populated by the
// retail extension handshake and deliberately read at report construction
// time; they are not process-global constants.
constexpr std::uint32_t kRmge01WpadControlBlockTable = 0x80660170u;
constexpr std::uint32_t kRmge01WpadExtensionAdditiveKeyOffset = 0x924u;
constexpr std::uint32_t kRmge01WpadExtensionXorKeyOffset = 0x92Cu;

constexpr std::uint64_t bluetooth_tick_deadline_after(
    std::uint64_t now_ticks,
    std::uint64_t delay_ticks) noexcept {
    return delay_ticks >
            std::numeric_limits<std::uint64_t>::max() - now_ticks
        ? std::numeric_limits<std::uint64_t>::max()
        : now_ticks + delay_ticks;
}

std::size_t virtual_wiimote_count() {
    char buffer[32]{};
    std::size_t length = 0;
    if (getenv_s(
            &length, buffer, sizeof(buffer), "GALAXY_VIRTUAL_WIIMOTE_COUNT") !=
            0 ||
        length <= 1) {
        return 1;
    }
    char* end = nullptr;
    const unsigned long parsed = std::strtoul(buffer, &end, 10);
    if (end == buffer || *end != '\0' || parsed == 0 ||
        parsed > kMaxVirtualWiimoteCount) {
        throw std::runtime_error(
            "GALAXY_VIRTUAL_WIIMOTE_COUNT must be in range 1..5");
    }
    return static_cast<std::size_t>(parsed);
}

std::array<std::uint8_t, 6> virtual_wiimote_bdaddr(std::size_t slot) {
    auto bdaddr = kWiimoteBdAddr;
    bdaddr[5] = static_cast<std::uint8_t>(slot);
    return bdaddr;
}

std::array<std::uint8_t, 6> sysconf_bdaddr_from_hci(
    const std::array<std::uint8_t, 6>& hci_bdaddr) {
    return {
        hci_bdaddr[5],
        hci_bdaddr[4],
        hci_bdaddr[3],
        hci_bdaddr[2],
        hci_bdaddr[1],
        hci_bdaddr[0],
    };
}

std::array<std::uint8_t, 16> virtual_wiimote_link_key(std::size_t slot) {
    std::array<std::uint8_t, 16> key{};
    for (std::size_t i = 0; i < key.size(); ++i) {
        key[i] = static_cast<std::uint8_t>(
            0xA0u + static_cast<unsigned>(slot));
    }
    return key;
}

void write_ascii_padded(
    std::vector<std::byte>& bytes,
    std::size_t offset,
    std::string_view ascii,
    std::size_t size) {
    for (std::size_t i = 0; i < size; ++i) {
        bytes[offset + i] = static_cast<std::byte>(
            i < ascii.size() ? static_cast<std::uint8_t>(ascii[i]) : 0u);
    }
}

template <std::size_t Size>
void write_u8_array(
    std::vector<std::byte>& bytes,
    std::size_t offset,
    const std::array<std::uint8_t, Size>& values) {
    for (std::size_t i = 0; i < Size; ++i) {
        bytes[offset + i] = static_cast<std::byte>(values[i]);
    }
}

std::vector<std::byte> create_bt_cdif() {
    std::vector<std::byte> bytes(0x205, std::byte{0});
    const std::size_t count = virtual_wiimote_count();
    bytes[0] = static_cast<std::byte>(count);
    constexpr std::size_t kCdifEntryBytes = 0x56;
    for (std::size_t slot = 0; slot < count; ++slot) {
        const std::size_t offset = 0x01 + slot * kCdifEntryBytes;
        const auto hci_bdaddr = virtual_wiimote_bdaddr(slot);
        const auto sysconf_bdaddr = sysconf_bdaddr_from_hci(hci_bdaddr);
        const auto link_key = virtual_wiimote_link_key(slot);
        write_u8_array(bytes, offset, sysconf_bdaddr);
        write_ascii_padded(bytes, offset + 0x06, "Nintendo RVL-CNT-01", 0x40);
        write_u8_array(bytes, offset + 0x46, link_key);
    }
    return bytes;
}

std::vector<std::byte> create_bt_dinf() {
    std::vector<std::byte> bytes(0x461, std::byte{0});
    const std::size_t count = virtual_wiimote_count();
    bytes[0] = static_cast<std::byte>(count);
    constexpr std::size_t kDinfEntryBytes = 0x46;
    constexpr std::size_t kActiveWiimoteOffset = 0x02BD;
    for (std::size_t slot = 0; slot < count; ++slot) {
        const auto hci_bdaddr = virtual_wiimote_bdaddr(slot);
        const auto sysconf_bdaddr = sysconf_bdaddr_from_hci(hci_bdaddr);
        const auto link_key = virtual_wiimote_link_key(slot);
        const std::size_t registered_offset = 0x01 + slot * kDinfEntryBytes;
        const std::size_t active_offset =
            kActiveWiimoteOffset + slot * kDinfEntryBytes;
        write_u8_array(bytes, registered_offset, sysconf_bdaddr);
        write_ascii_padded(
            bytes, registered_offset + 0x06, "Nintendo RVL-CNT-01", 0x40);
        write_u8_array(bytes, registered_offset + 0x26, link_key);
        write_u8_array(bytes, active_offset, sysconf_bdaddr);
        write_ascii_padded(
            bytes, active_offset + 0x06, "Nintendo RVL-CNT-01", 0x40);
        write_u8_array(bytes, active_offset + 0x26, link_key);
    }
    return bytes;
}

std::vector<std::byte> create_default_sysconf_file() {
    std::vector<SysconfEntry> entries;
    const auto add = [&](SysconfEntryType type,
                         std::string_view name,
                         std::vector<std::byte> bytes) {
        entries.push_back(SysconfEntry{type, name, std::move(bytes)});
    };
    const auto byte = [](std::uint8_t value) {
        return std::vector<std::byte>{std::byte{value}};
    };

    add(SysconfEntryType::BigArray, "BT.DINF", create_bt_dinf());
    add(SysconfEntryType::BigArray, "BT.CDIF", create_bt_cdif());
    add(SysconfEntryType::Long, "BT.SENS", be32_bytes(3));
    add(SysconfEntryType::Byte, "BT.BAR", byte(1));
    add(SysconfEntryType::Byte, "BT.SPKV", byte(0x58));
    add(SysconfEntryType::Byte, "BT.MOT", byte(1));
    add(SysconfEntryType::SmallArray, "IPL.NIK", utf16be_console_name("Galaxy"));
    add(SysconfEntryType::Byte, "IPL.LNG", byte(1));
    std::vector<std::byte> address_book(0x1008, std::byte{0});
    address_book[0] = std::byte{0x6C};
    add(SysconfEntryType::BigArray, "IPL.SADR", std::move(address_book));
    std::vector<std::byte> parental_control(0x4A, std::byte{0});
    parental_control[1] = std::byte{0x04};
    parental_control[2] = std::byte{0x14};
    add(SysconfEntryType::SmallArray, "IPL.PC", std::move(parental_control));
    add(SysconfEntryType::Long, "IPL.CB", be32_bytes(0));
    add(SysconfEntryType::Byte, "IPL.AR", byte(1));
    add(SysconfEntryType::Byte, "IPL.SSV", byte(1));
    add(SysconfEntryType::ByteBool, "IPL.CD", byte(0));
    add(SysconfEntryType::ByteBool, "IPL.CD2", byte(0));
    add(SysconfEntryType::ByteBool, "IPL.EULA", byte(1));
    add(SysconfEntryType::Byte, "IPL.UPT", byte(2));
    add(SysconfEntryType::Byte, "IPL.PGS", byte(0));
    add(SysconfEntryType::Byte, "IPL.E60", byte(1));
    add(SysconfEntryType::Byte, "IPL.DH", byte(0));
    add(SysconfEntryType::Long, "IPL.INC", be32_bytes(8));
    add(SysconfEntryType::Long, "IPL.FRC", be32_bytes(0x28));
    add(SysconfEntryType::SmallArray, "IPL.IDL", byte(0));
    entries.back().bytes.push_back(std::byte{1});
    add(SysconfEntryType::Long, "NET.WCFG", be32_bytes(1));
    add(SysconfEntryType::Long, "NET.CTPC", be32_bytes(0));
    add(SysconfEntryType::Byte, "WWW.RST", byte(0));
    add(SysconfEntryType::ByteBool, "MPLS.MOVIE", byte(1));

    std::vector<std::byte> buffer;
    buffer.reserve(kSysconfSize);
    buffer.insert(
        buffer.end(),
        {std::byte{'S'}, std::byte{'C'}, std::byte{'v'}, std::byte{'0'}});
    append_be16(buffer, static_cast<std::uint16_t>(entries.size()));

    const std::size_t entries_begin =
        buffer.size() + sizeof(std::uint16_t) * (entries.size() + 1u);
    std::vector<std::byte> entry_payload;
    for (const SysconfEntry& entry : entries) {
        append_be16(
            buffer,
            static_cast<std::uint16_t>(entries_begin + entry_payload.size()));
        const auto type = static_cast<std::uint8_t>(entry.type);
        entry_payload.push_back(static_cast<std::byte>(
            (type << 5u) |
            (static_cast<std::uint8_t>(entry.name.size()) - 1u)));
        for (const char ch : entry.name) {
            entry_payload.push_back(static_cast<std::byte>(ch));
        }
        if (entry.type == SysconfEntryType::BigArray) {
            append_be16(
                entry_payload,
                static_cast<std::uint16_t>(entry.bytes.size() - 1u));
        } else if (entry.type == SysconfEntryType::SmallArray) {
            entry_payload.push_back(
                static_cast<std::byte>(entry.bytes.size() - 1u));
        }
        entry_payload.insert(
            entry_payload.end(),
            entry.bytes.begin(),
            entry.bytes.end());
    }
    append_be16(
        buffer,
        static_cast<std::uint16_t>(entries_begin + entry_payload.size()));
    buffer.insert(buffer.end(), entry_payload.begin(), entry_payload.end());
    buffer.resize(kSysconfSize, std::byte{0});
    buffer[kSysconfSize - 4u] = std::byte{'S'};
    buffer[kSysconfSize - 3u] = std::byte{'C'};
    buffer[kSysconfSize - 2u] = std::byte{'e'};
    buffer[kSysconfSize - 1u] = std::byte{'d'};
    return buffer;
}

std::vector<std::byte> create_default_setting_txt_file() {
    std::vector<std::byte> bytes(kSettingTxtSize, std::byte{0});
    std::uint32_t key = 0x73B5DBFAu;
    std::size_t position = 0;
    const auto write_byte = [&](char ch) {
        if (position >= bytes.size()) {
            return;
        }
        bytes[position++] = static_cast<std::byte>(
            static_cast<std::uint8_t>(ch) ^ static_cast<std::uint8_t>(key));
        key = (key >> 31u) | (key << 1u);
    };
    const auto write_line = [&](std::string_view key_name,
                                std::string_view value) {
        for (const char ch : key_name) write_byte(ch);
        write_byte('=');
        for (const char ch : value) write_byte(ch);
        write_byte('\r');
        write_byte('\n');
    };

    write_line("AREA", "USA");
    write_line("MODEL", "RVL-001(USA)");
    write_line("DVD", "0");
    write_line("MPCH", "0x7FFE");
    write_line("CODE", "LU");
    write_line("SERNO", "000000000");
    write_line("VIDEO", "NTSC");
    write_line("GAME", "US");
    return bytes;
}

std::vector<std::byte> create_default_play_rec_file() {
    return std::vector<std::byte>(kPlayRecSize, std::byte{0});
}

std::vector<std::byte> create_empty_rfl_database() {
    std::vector<std::byte> db(kRflDatabaseSize, std::byte{0});
    write_be32(db, 0x0000, kRflOfficialMagic);
    // Keep the fallback copyright-neutral and conservative: provide a valid
    // empty FaceLib container, but do not invent packed face feature data.
    write_be32(db, kRflDatabaseIsolationOffset, 0x80000000u);
    write_be32(db, kRflDatabaseHiddenOffset + 0x00, kRflHiddenMagic);
    write_be16(db, kRflDatabaseHiddenOffset + 0x04, 0xFFFFu);
    write_be16(db, kRflDatabaseHiddenOffset + 0x06, 0xFFFFu);
    for (std::size_t i = 0; i < kRflHiddenTableEntries; ++i) {
        const std::size_t offset =
            kRflHiddenTableOffset + i * kRflHiddenTableEntrySize;
        write_be16(db, offset + 0x08, 0x7FFFu);
        write_be16(db, offset + 0x0A, 0x7FFFu);
    }
    write_be16(db, kRflDatabaseSize - 2, 0);
    write_be16(db, kRflDatabaseSize - 2, rfl_crc(db));
    return db;
}

bool is_generated_empty_rfl_database(std::span<const std::byte> db) {
    const std::vector<std::byte> empty = create_empty_rfl_database();
    return db.size() == empty.size() &&
        std::equal(empty.begin(), empty.end(), db.begin());
}

bool is_facelib_database_path(std::string_view path) {
    return path == kRflDatabasePath;
}

bool is_sysconf_path(std::string_view path) {
    return path == kSysconfPath;
}

bool is_setting_txt_path(std::string_view path) {
    return path == kSettingTxtPath;
}

bool is_play_rec_path(std::string_view path) {
    return path == kPlayRecPath;
}

bool is_modeled_system_nand_path(std::string_view path) {
    return is_sysconf_path(path) ||
        is_setting_txt_path(path) ||
        is_play_rec_path(path);
}

bool is_valid_sysconf_file(std::span<const std::byte> bytes) {
    if (bytes.size() != kSysconfSize ||
        bytes[0] != std::byte{'S'} ||
        bytes[1] != std::byte{'C'} ||
        bytes[2] != std::byte{'v'} ||
        bytes[3] != std::byte{'0'} ||
        bytes[kSysconfSize - 4u] != std::byte{'S'} ||
        bytes[kSysconfSize - 3u] != std::byte{'C'} ||
        bytes[kSysconfSize - 2u] != std::byte{'e'} ||
        bytes[kSysconfSize - 1u] != std::byte{'d'}) {
        return false;
    }

    const auto read_be16 = [&](std::size_t offset) -> std::uint16_t {
        return static_cast<std::uint16_t>(
            (std::to_integer<std::uint16_t>(bytes[offset]) << 8u) |
            std::to_integer<std::uint16_t>(bytes[offset + 1u]));
    };
    const std::uint16_t count = read_be16(4u);
    const std::size_t table_end =
        6u + (static_cast<std::size_t>(count) + 1u) * sizeof(std::uint16_t);
    if (table_end > kSysconfSize - 4u) {
        return false;
    }

    std::size_t expected_offset = table_end;
    for (std::uint16_t i = 0; i < count; ++i) {
        const std::size_t item_offset =
            read_be16(6u + static_cast<std::size_t>(i) * sizeof(std::uint16_t));
        if (item_offset != expected_offset ||
            item_offset >= kSysconfSize - 4u) {
            return false;
        }

        const std::uint8_t header =
            std::to_integer<std::uint8_t>(bytes[item_offset]);
        const std::uint8_t type = header & 0xE0u;
        const std::size_t name_length =
            static_cast<std::size_t>((header & 0x1Fu) + 1u);
        std::size_t cursor = item_offset + 1u + name_length;
        std::size_t data_size = 0;
        if (cursor > kSysconfSize - 4u) {
            return false;
        }
        switch (type) {
        case 0x20u:
            if (cursor + 2u > kSysconfSize - 4u) {
                return false;
            }
            data_size = static_cast<std::size_t>(read_be16(cursor)) + 1u;
            cursor += 2u;
            break;
        case 0x40u:
            if (cursor + 1u > kSysconfSize - 4u) {
                return false;
            }
            data_size =
                static_cast<std::size_t>(
                    std::to_integer<std::uint8_t>(bytes[cursor])) +
                1u;
            cursor += 1u;
            break;
        case 0x60u:
        case 0xE0u:
            data_size = 1u;
            break;
        case 0x80u:
            data_size = 2u;
            break;
        case 0xA0u:
            data_size = 4u;
            break;
        case 0xC0u:
            data_size = 8u;
            break;
        default:
            return false;
        }
        if (cursor + data_size > kSysconfSize - 4u) {
            return false;
        }
        expected_offset = cursor + data_size;
    }

    return read_be16(
               6u + static_cast<std::size_t>(count) * sizeof(std::uint16_t)) ==
        expected_offset;
}

std::uint16_t read_sysconf_be16(std::span<const std::byte> bytes,
                                std::size_t offset) {
    return static_cast<std::uint16_t>(
        (std::to_integer<std::uint16_t>(bytes[offset]) << 8u) |
        std::to_integer<std::uint16_t>(bytes[offset + 1u]));
}

bool is_valid_setting_txt_file(std::span<const std::byte> bytes) {
    if (bytes.size() != kSettingTxtSize) {
        return false;
    }

    // Nintendo's reader stops on a zero byte in the encoded stream, not on a
    // decoded NUL.  A genuine 0x100-byte setting.txt therefore has a nonempty
    // encoded prefix followed by an all-zero tail.  Requiring that exact
    // termination makes missing-metadata migration content-proven instead of
    // accepting arbitrary ciphertext that happens to contain key substrings.
    const auto terminator = std::ranges::find(bytes, std::byte{0});
    if (terminator == bytes.begin() || terminator == bytes.end() ||
        !std::ranges::all_of(terminator, bytes.end(), [](std::byte value) {
            return value == std::byte{0};
        })) {
        return false;
    }

    std::string decoded;
    decoded.reserve(static_cast<std::size_t>(terminator - bytes.begin()));
    std::uint32_t key = 0x73B5DBFAu;
    for (auto it = bytes.begin(); it != terminator; ++it) {
        const char ch = static_cast<char>(
            std::to_integer<std::uint8_t>(*it) ^
            static_cast<std::uint8_t>(key));
        key = (key >> 31u) | (key << 1u);
        const unsigned char byte = static_cast<unsigned char>(ch);
        if (ch != '\r' && ch != '\n' && (byte < 0x20u || byte > 0x7Eu)) {
            return false;
        }
        if (ch != '\r') decoded.push_back(ch);
    }

    constexpr std::array<std::pair<std::string_view, std::string_view>, 8>
        kRequiredSettings{{
            {"AREA", "USA"},
            {"MODEL", "RVL-001(USA)"},
            {"DVD", "0"},
            {"MPCH", "0x7FFE"},
            {"CODE", "LU"},
            {"SERNO", ""},
            {"VIDEO", "NTSC"},
            {"GAME", "US"},
        }};
    std::array<bool, kRequiredSettings.size()> seen{};
    std::size_t line_begin = 0u;
    while (line_begin <= decoded.size()) {
        const std::size_t line_end = decoded.find('\n', line_begin);
        const std::string_view line(
            decoded.data() + line_begin,
            (line_end == std::string::npos ? decoded.size() : line_end) -
                line_begin);
        if (!line.empty()) {
            const std::size_t equals = line.find('=');
            if (equals == std::string_view::npos || equals == 0u ||
                equals + 1u >= line.size() ||
                line.find('=', equals + 1u) != std::string_view::npos) {
                return false;
            }
            const std::string_view name = line.substr(0u, equals);
            const std::string_view value = line.substr(equals + 1u);
            const auto required = std::ranges::find_if(
                kRequiredSettings,
                [&](const auto& setting) { return setting.first == name; });
            if (required == kRequiredSettings.end()) return false;
            const std::size_t index = static_cast<std::size_t>(
                required - kRequiredSettings.begin());
            if (seen[index]) return false;
            if (name == "SERNO") {
                if (value.empty() || value.size() > 9u ||
                    !std::ranges::all_of(value, [](char ch) {
                        return ch >= '0' && ch <= '9';
                    })) {
                    return false;
                }
            } else if (value != required->second) {
                return false;
            }
            seen[index] = true;
        }
        if (line_end == std::string::npos) break;
        line_begin = line_end + 1u;
    }
    return std::ranges::all_of(seen, [](bool value) { return value; });
}

bool is_valid_play_rec_file(std::span<const std::byte> bytes) {
    if (bytes.size() != kPlayRecSize) {
        return false;
    }
    const auto read_be32_at = [&](std::size_t offset) {
        return (std::to_integer<std::uint32_t>(bytes[offset]) << 24u) |
            (std::to_integer<std::uint32_t>(bytes[offset + 1u]) << 16u) |
            (std::to_integer<std::uint32_t>(bytes[offset + 2u]) << 8u) |
            std::to_integer<std::uint32_t>(bytes[offset + 3u]);
    };
    std::uint32_t checksum = 0u;
    for (std::size_t offset = 4u; offset < bytes.size(); offset += 4u) {
        checksum += read_be32_at(offset);
    }
    return read_be32_at(0u) == checksum;
}

bool is_valid_rmge_game_data(std::span<const std::byte> bytes) {
    constexpr std::size_t kExpectedSize = 0xBE00u;
    if (bytes.size() != kExpectedSize) {
        return false;
    }
    const auto read_be32_at = [&](std::size_t offset) {
        return (std::to_integer<std::uint32_t>(bytes[offset]) << 24u) |
            (std::to_integer<std::uint32_t>(bytes[offset + 1u]) << 16u) |
            (std::to_integer<std::uint32_t>(bytes[offset + 2u]) << 8u) |
            std::to_integer<std::uint32_t>(bytes[offset + 3u]);
    };
    if (read_be32_at(4u) != 2u || read_be32_at(8u) != 19u ||
        read_be32_at(12u) != kExpectedSize) {
        return false;
    }
    constexpr std::array<std::string_view, 19> kNames{
        "mario1", "luigi1", "config1", "mario2", "luigi2", "config2",
        "mario3", "luigi3", "config3", "mario4", "luigi4", "config4",
        "mario5", "luigi5", "config5", "mario6", "luigi6", "config6",
        "sysconf",
    };
    constexpr std::array<std::uint32_t, 19> kOffsets{
        0x140u, 0x10C0u, 0x2040u, 0x20A0u, 0x3020u, 0x3FA0u,
        0x4000u, 0x4F80u, 0x5F00u, 0x5F60u, 0x6EE0u, 0x7E60u,
        0x7EC0u, 0x8E40u, 0x9DC0u, 0x9E20u, 0xADA0u, 0xBD20u,
        0xBD80u,
    };
    for (std::size_t index = 0; index < kNames.size(); ++index) {
        const std::size_t info = 0x10u + index * 0x10u;
        const char* name = reinterpret_cast<const char*>(bytes.data() + info);
        const std::size_t length = strnlen_s(name, 12u);
        if (length == 12u || std::string_view(name, length) != kNames[index] ||
            read_be32_at(info + 12u) != kOffsets[index]) {
            return false;
        }
    }
    std::uint16_t sum = 0u;
    std::uint16_t inverse_sum = 0u;
    for (std::size_t offset = 4u; offset < kExpectedSize; offset += 2u) {
        const std::uint16_t word = static_cast<std::uint16_t>(
            (std::to_integer<std::uint16_t>(bytes[offset]) << 8u) |
            std::to_integer<std::uint16_t>(bytes[offset + 1u]));
        sum = static_cast<std::uint16_t>(sum + word);
        inverse_sum = static_cast<std::uint16_t>(inverse_sum +
            static_cast<std::uint16_t>(~word));
    }
    return read_be32_at(0u) ==
        ((static_cast<std::uint32_t>(sum) << 16u) | inverse_sum);
}

bool is_valid_rmge_banner(std::span<const std::byte> bytes) {
    if (bytes.size() != 0x72A0u || bytes[0] != std::byte{'W'} ||
        bytes[1] != std::byte{'I'} || bytes[2] != std::byte{'B'} ||
        bytes[3] != std::byte{'N'}) {
        return false;
    }
    const std::uint32_t flags =
        (std::to_integer<std::uint32_t>(bytes[4]) << 24u) |
        (std::to_integer<std::uint32_t>(bytes[5]) << 16u) |
        (std::to_integer<std::uint32_t>(bytes[6]) << 8u) |
        std::to_integer<std::uint32_t>(bytes[7]);
    const std::uint16_t icon_speed = static_cast<std::uint16_t>(
        (std::to_integer<std::uint16_t>(bytes[8]) << 8u) |
        std::to_integer<std::uint16_t>(bytes[9]));
    // A one-icon banner must terminate after the first packed two-bit speed.
    // Real RMGE01 saves exist with both NORMAL (2) and SLOW (3), so accept
    // either source-proven speed without rewriting the guest bytes.
    return flags == 0u && (icon_speed == 2u || icon_speed == 3u) &&
        std::ranges::all_of(
            bytes.subspan(10u, 22u),
            [](std::byte value) { return value == std::byte{0}; });
}

bool is_valid_rfl_database(std::span<const std::byte> db) {
    return db.size() == kRflDatabaseSize &&
        db[0] == std::byte{0x52} && db[1] == std::byte{0x4E} &&
        db[2] == std::byte{0x4F} && db[3] == std::byte{0x44} &&
        db[kRflDatabaseHiddenOffset + 0] == std::byte{0x52} &&
        db[kRflDatabaseHiddenOffset + 1] == std::byte{0x4E} &&
        db[kRflDatabaseHiddenOffset + 2] == std::byte{0x48} &&
        db[kRflDatabaseHiddenOffset + 3] == std::byte{0x44} &&
        rfl_crc(db) == 0;
}

std::optional<std::filesystem::path> get_env_path(const wchar_t* name) {
    wchar_t buffer[MAX_PATH]{};
    const DWORD length = GetEnvironmentVariableW(name, buffer, MAX_PATH);
    if (length == 0 || length >= MAX_PATH) {
        return std::nullopt;
    }
    return std::filesystem::path(buffer);
}

bool read_env_flag(const char* name, bool default_value = false) {
    char buffer[32]{};
    std::size_t length = 0;
    if (getenv_s(&length, buffer, sizeof(buffer), name) != 0 ||
        length <= 1) {
        return default_value;
    }
    return buffer[0] != '0' && buffer[0] != 'f' && buffer[0] != 'F' &&
           buffer[0] != 'n' && buffer[0] != 'N';
}

thread_local NativeInputPollBreakdown s_input_poll_breakdown{};
thread_local bool s_input_poll_breakdown_active{};
thread_local std::uint64_t s_input_poll_stage_started_ns{};
thread_local std::size_t s_input_poll_stage{};

std::uint64_t input_poll_steady_ns() noexcept {
    return static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count());
}

void input_poll_diagnostic_stage(NativeInputPollStage stage) noexcept {
    if (!s_input_poll_breakdown_active) return;
    const auto now = input_poll_steady_ns();
    if (now >= s_input_poll_stage_started_ns) {
        s_input_poll_breakdown.stage_ns[s_input_poll_stage] += now - s_input_poll_stage_started_ns;
    }
    s_input_poll_stage_started_ns = now;
    s_input_poll_stage = static_cast<std::size_t>(stage);
}

class InputPollBreakdownScope final {
public:
    InputPollBreakdownScope() noexcept {
        static const bool enabled = read_env_flag("GALAXY_DIAGNOSTIC_INPUT_POLL_BREAKDOWN", false);
        if (!enabled || s_input_poll_breakdown_active) return;
        owns_ = true;
        const auto serial = s_input_poll_breakdown.serial + 1u;
        s_input_poll_breakdown = {};
        s_input_poll_breakdown.enabled = true;
        s_input_poll_breakdown.serial = serial;
        start_ = input_poll_steady_ns();
        s_input_poll_stage_started_ns = start_;
        s_input_poll_stage = static_cast<std::size_t>(NativeInputPollStage::Reconnect);
        s_input_poll_breakdown_active = true;
    }
    ~InputPollBreakdownScope() noexcept {
        if (!owns_) return;
        const auto end = input_poll_steady_ns();
        if (end >= s_input_poll_stage_started_ns) {
            s_input_poll_breakdown.stage_ns[s_input_poll_stage] += end - s_input_poll_stage_started_ns;
        }
        s_input_poll_breakdown.total_ns = end >= start_ ? end - start_ : 0u;
        s_input_poll_breakdown_active = false;
    }
    InputPollBreakdownScope(const InputPollBreakdownScope&) = delete;
    InputPollBreakdownScope& operator=(const InputPollBreakdownScope&) = delete;
private:
    bool owns_{};
    std::uint64_t start_{};
};

float read_env_float_setting(
    const char* name,
    float default_value,
    float min_value,
    float max_value) {
    char buffer[64]{};
    std::size_t length = 0;
    if (getenv_s(&length, buffer, sizeof(buffer), name) != 0) {
        throw std::runtime_error(
            std::string("environment variable is too long: ") + name);
    }
    if (length <= 1) {
        return default_value;
    }
    char* end = nullptr;
    const float parsed = std::strtof(buffer, &end);
    if (end == buffer || *end != '\0' || !std::isfinite(parsed)) {
        throw std::runtime_error(
            std::string("invalid float environment value for ") + name);
    }
    return std::clamp(parsed, min_value, max_value);
}

int read_env_int_setting(
    const char* name,
    int default_value,
    int min_value,
    int max_value) {
    char buffer[64]{};
    std::size_t length = 0;
    if (getenv_s(&length, buffer, sizeof(buffer), name) != 0) {
        throw std::runtime_error(
            std::string("environment variable is too long: ") + name);
    }
    if (length <= 1) {
        return default_value;
    }
    char* end = nullptr;
    const long parsed = std::strtol(buffer, &end, 10);
    if (end == buffer || *end != '\0') {
        throw std::runtime_error(
            std::string("invalid integer environment value for ") + name);
    }
    return std::clamp(
        static_cast<int>(parsed), min_value, max_value);
}

