// Read an environment variable as a filesystem path.  Returns an empty string
// when the variable is unset or empty.  Used by the DSP ucode dump hook so an
// install can capture the real RMGE01 jdsp IRAM image by booting once with
// GALAXY_DSP_DUMP_UCODE=<path> set.
std::string read_env_path(const char* name) {
    char buffer[1024]{};
    std::size_t length = 0;
    if (getenv_s(&length, buffer, sizeof(buffer), name) != 0 || length <= 1) {
        return std::string{};
    }
    return std::string{buffer};
}

bool trace_bluetooth() {
    static const bool enabled = read_env_flag("GALAXY_TRACE_BLUETOOTH");
    return enabled;
}

bool trace_boot_input() {
    static const bool enabled = read_env_flag("GALAXY_TRACE_BOOT_INPUT");
    return enabled;
}

// CP FIFO setup happens on the real-time guest thread during the first VI
// interval.  Keep its diagnostic logging explicitly opt-in: flushing a
// redirected stdout handle here can consume an entire 60 Hz deadline and make
// an otherwise healthy native run fail the cadence audit.
bool trace_cp_fifo() {
    static const bool enabled = read_env_flag("GALAXY_TRACE_CP_FIFO");
    return enabled;
}

bool trace_input_proof_compact() {
    static const bool enabled =
        read_env_flag("GALAXY_TRACE_INPUT_PROOF_COMPACT");
    return enabled;
}

std::uint64_t read_env_u64_setting(
    const char* name,
    std::uint64_t default_value) {
    char buffer[64]{};
    std::size_t length = 0;
    if (getenv_s(&length, buffer, sizeof(buffer), name) != 0) {
        throw std::runtime_error(
            std::string("environment variable is too long: ") + name);
    }
    if (length <= 1) {
        return default_value;
    }
    char* end = nullptr;
    const unsigned long long parsed = std::strtoull(buffer, &end, 10);
    if (end == buffer || *end != '\0') {
        throw std::runtime_error(
            std::string("invalid integer environment value for ") + name);
    }
    return static_cast<std::uint64_t>(parsed);
}

bool trace_boot_input_at(std::uint64_t current_vi) {
    if (!trace_boot_input()) {
        return false;
    }
    static const std::uint64_t start =
        read_env_u64_setting("GALAXY_TRACE_BOOT_INPUT_START_VI", 0);
    static const std::uint64_t end =
        read_env_u64_setting("GALAXY_TRACE_BOOT_INPUT_END_VI", 0);
    return current_vi >= start && (end == 0 || current_vi <= end);
}

bool trace_boot_input_sample_at(
    std::uint64_t current_vi,
    bool interesting = false) {
    if (!trace_boot_input_at(current_vi)) {
        return false;
    }
    if (interesting && !trace_input_proof_compact()) {
        return true;
    }
    static const std::uint64_t start =
        read_env_u64_setting("GALAXY_TRACE_BOOT_INPUT_START_VI", 0);
    static const std::uint64_t first_full_samples =
        read_env_u64_setting("GALAXY_TRACE_BOOT_INPUT_INITIAL_SAMPLES", 8);
    static const std::uint64_t interval =
        read_env_u64_setting("GALAXY_TRACE_BOOT_INPUT_INTERVAL_VI", 30);
    const std::uint64_t elapsed = current_vi >= start ? current_vi - start : 0;
    if (elapsed < first_full_samples) {
        return true;
    }
    return interval == 0 || (elapsed % interval) == 0;
}

std::ostream& write_wiimote_ir_gate_trace_fields(
    std::ostream& out,
    bool report13_enabled,
    bool report1a_enabled,
    bool sensitivity_block1_seen,
    bool sensitivity_block2_seen,
    bool latch_seen,
    std::uint8_t mode) {
    const bool enabled =
        report13_enabled &&
        report1a_enabled &&
        sensitivity_block1_seen &&
        sensitivity_block2_seen &&
        latch_seen &&
        mode != 0u;
    out << " irgate=" << (enabled ? 1 : 0)
        << " ir13=" << (report13_enabled ? 1 : 0)
        << " ir1a=" << (report1a_enabled ? 1 : 0)
        << " sens1=" << (sensitivity_block1_seen ? 1 : 0)
        << " sens2=" << (sensitivity_block2_seen ? 1 : 0)
        << " latch=" << (latch_seen ? 1 : 0)
        << " irmode=0x" << std::hex << static_cast<unsigned>(mode)
        << std::dec;
    return out;
}

std::span<const std::uint8_t> wiimote_report_ir_wire_bytes(
    std::span<const std::uint8_t> report) {
    if (report.size() < 2u) {
        return {};
    }
    std::size_t offset = 0;
    std::size_t size = 0;
    switch (report[1]) {
    case 0x33u:
        offset = 7u;
        size = 12u;
        break;
    case 0x36u:
        offset = 4u;
        size = 10u;
        break;
    case 0x37u:
        offset = 7u;
        size = 10u;
        break;
    default:
        return {};
    }
    if (offset + size > report.size()) {
        throw std::runtime_error("native Wiimote IR report was truncated");
    }
    return report.subspan(offset, size);
}

struct VirtualInputAclPayloadIdentity {
    std::uint8_t report_id{};
    std::uint32_t payload_size{};
    std::array<
        std::uint8_t,
        galaxy::input::kMaxWiimoteInputReportBytes> payload{};
    std::uint64_t fingerprint{};
};

VirtualInputAclPayloadIdentity virtual_input_acl_payload_identity(
    std::span<const std::byte> framed_acl) {
    constexpr std::size_t kAclAndL2capHeaderBytes = 8u;
    constexpr std::uint64_t kFnv1a64OffsetBasis =
        14'695'981'039'346'656'037ull;
    constexpr std::uint64_t kFnv1a64Prime = 1'099'511'628'211ull;
    if (framed_acl.size() < kAclAndL2capHeaderBytes + 2u ||
        framed_acl[kAclAndL2capHeaderBytes] != std::byte{0xA1}) {
        throw std::runtime_error(
            "virtual Wii Remote input ACL has no HID Interrupt IN payload");
    }

    const std::span<const std::byte> hid_payload =
        framed_acl.subspan(kAclAndL2capHeaderBytes);
    if (hid_payload.size() > galaxy::input::kMaxWiimoteInputReportBytes) {
        throw std::runtime_error(
            "virtual Wii Remote input ACL payload exceeds the native report bound");
    }
    VirtualInputAclPayloadIdentity identity{};
    identity.report_id = static_cast<std::uint8_t>(hid_payload[1]);
    identity.payload_size =
        static_cast<std::uint32_t>(hid_payload.size());
    std::uint64_t fingerprint = kFnv1a64OffsetBasis;
    for (std::size_t i = 0; i < hid_payload.size(); ++i) {
        const std::uint8_t value =
            static_cast<std::uint8_t>(hid_payload[i]);
        identity.payload[i] = value;
        fingerprint ^= static_cast<std::uint64_t>(value);
        fingerprint *= kFnv1a64Prime;
    }
    identity.fingerprint = fingerprint;
    return identity;
}

bool wiimote_ir_camera_layout_compatible(
    std::uint8_t report_mode,
    std::uint8_t camera_mode) noexcept {
    switch (report_mode) {
    case 0x33u:
        return camera_mode == 0x03u;
    case 0x36u:
    case 0x37u:
        return camera_mode == 0x01u;
    default:
        return true;
    }
}

// Native Wiimote Bluetooth data path: the runtime synthesizes an
// inbound Wiimote connection at the HCI/L2CAP boundary so the game's own
// BT/WPAD/KPAD code runs natively. This is the carrier for ALL input sources
// (keyboard/mouse, controller, and real Wii Remote passthrough). It defaults on
// for the no-HLE product path; tests can still force it off when explicitly
// covering unsupported Bluetooth device traffic.
bool native_bt_wiimote() {
    return read_env_flag("GALAXY_NATIVE_BT_WIIMOTE", true);
}

