std::uint32_t read_guest_u32_or(
    const GuestAddressSpace& address_space,
    std::uint32_t address,
    std::uint32_t fallback = 0xffffffffu) {
    return address_space.pointer_or_null(address, 4u) != nullptr
        ? address_space.read_u32(address)
        : fallback;
}

std::uint8_t read_guest_u8_or(
    const GuestAddressSpace& address_space,
    std::uint32_t address,
    std::uint8_t fallback = 0xffu) {
    const std::byte* const value = address_space.pointer_or_null(address, 1u);
    return value != nullptr ? std::to_integer<std::uint8_t>(*value) : fallback;
}

void append_jaudio_dsp_state(
    std::ostream& out,
    const GuestAddressSpace& address_space) {
    out << " jaudio-subframes="
        << read_guest_u32_or(address_space, kJAudioSubFramesAddress)
        << " jaudio-sn="
        << read_guest_u32_or(address_space, kJAudioDspSyncCountAddress)
        << " jaudio-dac-status="
        << read_guest_u32_or(address_space, kJAudioDspStatusAddress)
        << " jaudio-dac-count="
        << static_cast<unsigned>(
               read_guest_u8_or(address_space, kJAudioDacBufferCountAddress))
        << " jaudio-dac-write="
        << read_guest_u32_or(address_space, kJAudioDspDacWriteBufferAddress)
        << " jaudio-dac-read="
        << read_guest_u32_or(address_space, kJAudioDspDacReadBufferAddress)
        << " jaudio-dac-buf=0x" << std::hex
        << read_guest_u32_or(address_space, kJAudioDspDacBufferAddress, 0u)
        << " jaudio-task-state=0x"
        << static_cast<unsigned>(
               read_guest_u8_or(address_space, kJAudioDspTaskStateAddress))
        << " jaudio-task-mode=0x"
        << static_cast<unsigned>(
               read_guest_u8_or(address_space, kJAudioDspTaskModeAddress))
        << " jaudio-base=0x"
        << read_guest_u32_or(address_space, kJAudioDspBaseTaskAddress, 0u)
        << " jaudio-active=0x"
        << read_guest_u32_or(address_space, kJAudioDspActiveTaskAddress, 0u)
        << " jaudio-next=0x"
        << read_guest_u32_or(address_space, kJAudioDspNextTaskAddress, 0u)
        << std::dec;
}

