constexpr std::uint64_t kMaxDiscModOverrideBytes = 128ull << 20;
constexpr char kDiscModGameId[] = "RMGE01";
constexpr char kDiscModMainDolSha1[] =
    "9a71008ae1ee9010e267fa67d1f0b0d4f0e895dd";

bool has_parent_reference(const std::filesystem::path& path) {
    for (const auto& part : path) {
        if (part == L"..") {
            return true;
        }
    }
    return false;
}

std::uint64_t parse_u64_token(
    const std::string& token,
    const std::filesystem::path& manifest,
    std::size_t line_number,
    const char* field) {
    std::size_t consumed = 0;
    try {
        const std::uint64_t value = std::stoull(token, &consumed, 0);
        if (consumed == token.size()) {
            return value;
        }
    } catch (const std::exception&) {
    }
    std::ostringstream message;
    message << "malformed disc mod manifest " << manifest.string()
            << ':' << line_number << " invalid " << field << " '"
            << token << "'";
    throw std::runtime_error(message.str());
}

std::vector<std::byte> read_exact_mod_file(
    const std::filesystem::path& path,
    std::uint64_t expected_size) {
    if (expected_size == 0 || expected_size > kMaxDiscModOverrideBytes) {
        std::ostringstream message;
        message << "disc mod override " << path.string()
                << " has unsupported size " << expected_size;
        throw std::runtime_error(message.str());
    }
    std::error_code ec;
    const std::uint64_t actual_size = std::filesystem::file_size(path, ec);
    if (ec || actual_size != expected_size) {
        std::ostringstream message;
        message << "disc mod override " << path.string()
                << " size mismatch: manifest=" << expected_size
                << " file=" << (ec ? 0u : actual_size);
        throw std::runtime_error(message.str());
    }

    std::ifstream file(path, std::ios::binary);
    if (!file) {
        throw std::runtime_error(
            "failed to open disc mod override " + path.string());
    }
    std::vector<std::byte> bytes(static_cast<std::size_t>(expected_size));
    if (!bytes.empty()) {
        file.read(reinterpret_cast<char*>(bytes.data()),
                  static_cast<std::streamsize>(bytes.size()));
    }
    if (!file || file.gcount() != static_cast<std::streamsize>(bytes.size())) {
        throw std::runtime_error(
            "failed to read disc mod override " + path.string());
    }
    return bytes;
}

std::uint32_t trace_di_io_log_limit() {
    static const std::uint32_t limit = [] {
        char buffer[32]{};
        std::size_t length = 0;
        if (getenv_s(
                &length,
                buffer,
                sizeof(buffer),
                "GALAXY_TRACE_DI_IO_LIMIT") != 0 ||
            length <= 1) {
            return 64u;
        }
        char* end = nullptr;
        const unsigned long parsed = std::strtoul(buffer, &end, 10);
        if (end == buffer) {
            return 64u;
        }
        return static_cast<std::uint32_t>(
            std::min<unsigned long>(parsed, 1'000'000ul));
    }();
    return limit;
}

bool trace_di_io_counter_allows(std::uint32_t& counter) {
    const std::uint32_t limit = trace_di_io_log_limit();
    const bool allowed = limit == 0u || counter < limit;
    ++counter;
    return allowed;
}

