constexpr std::uint32_t kWiimoteExtensionRegisterBase = 0xA40000;
constexpr std::uint32_t kWiimoteSpeakerRegisterBase = 0xA20000;
constexpr std::uint32_t kWiimoteIrRegisterBase = 0xB00000;
constexpr std::uint32_t kWiimoteRegisterPageMask = 0xFFFF00;
constexpr std::uint32_t kWudPatchCommandBytes = 13;
constexpr std::uint32_t kPiCpBase = 0x300Cu;
constexpr std::uint32_t kPiCpTop = 0x3010u;
constexpr std::uint32_t kPiCpWrite = 0x3014u;
constexpr std::uint32_t kPiCpWrapMask = 0x20000000u;
constexpr std::uint32_t kGatherPipeBurstSize = 32u;
constexpr std::uint32_t kFifoAddressMask = 0x0FFFFFE0u;

std::uint32_t wiimote_output_report_size(std::uint8_t report_id) {
    // Sizes include the Bluetooth HID transaction byte (A2) and report id.
    switch (report_id) {
    case 0x10u:  // rumble only
    case 0x11u:  // LEDs
    case 0x13u:  // IR enable, part 1
    case 0x14u:  // speaker enable
    case 0x15u:  // status request
    case 0x19u:  // speaker mute
    case 0x1Au:  // IR enable, part 2
        return 3u;
    case 0x12u:  // data reporting mode
        return 4u;
    case 0x16u:  // write memory/registers: common + addr[3] + size + data[16]
    case 0x18u:  // speaker data: common + data[20]
        return 23u;
    case 0x17u:  // read memory/registers: common + addr[3] + size[2]
        return 8u;
    default:
        return 0u;
    }
}

std::array<std::uint8_t, kWiimoteEepromBytes> create_virtual_wiimote_eeprom() {
    std::array<std::uint8_t, kWiimoteEepromBytes> eeprom{};
    // The SDK reads two duplicate 11-byte DPD blocks followed by two duplicate
    // 10-byte accelerometer blocks. Use a neutral virtual sensor bar and a
    // checksum-valid upright accelerometer calibration so KPAD can trust IR.
    const std::array<std::uint8_t, 11> ir_calibration{
        0x7f, 0xa2, 0x8b, 0x80, 0xa2, 0x80, 0x5d, 0x30, 0x7f, 0x5d, 0x0c};
    for (std::size_t i = 0; i < ir_calibration.size(); ++i) {
        eeprom[i] = ir_calibration[i];
        eeprom[0x0Bu + i] = ir_calibration[i];
    }
    const std::array<std::uint8_t, 10> accel_calibration{
        0x80, 0x80, 0x80, 0x00, 0x99, 0x99, 0x99, 0x00, 0x00, 0xa0};
    for (std::size_t i = 0; i < accel_calibration.size(); ++i) {
        eeprom[0x16u + i] = accel_calibration[i];
        eeprom[0x20u + i] = accel_calibration[i];
    }
    return eeprom;
}

std::array<std::uint8_t, 256> create_virtual_nunchuk_registers(
    bool initialized) {
    std::array<std::uint8_t, 256> regs{};
    regs.fill(0xff);
    if (!initialized) {
        return regs;
    }

    regs.fill(0);
    // Captured RVL-CNT-01 Nunchuk calibration: accelerometer 0G/1G plus
    // stick max/min/center. Keep reports aligned with these centers so title
    // screens that demand a neutral Control Stick accept the virtual device.
    const std::array<std::uint8_t, 16> calibration{
        0x7d, 0x7e, 0x7a, 0x3c, 0xb1, 0xaf, 0xae, 0x1b,
        0xe0, 0x15, 0x7b, 0xe6, 0x1d, 0x81, 0x23, 0x78};
    for (std::size_t i = 0; i < calibration.size(); ++i) {
        regs[0x20u + i] = calibration[i];
    }
    const std::array<std::uint8_t, 6> nunchuk_id{
        0x00, 0x00, 0xa4, 0x20, 0x00, 0x00};
    for (std::size_t i = 0; i < nunchuk_id.size(); ++i) {
        regs[0xFAu + i] = nunchuk_id[i];
    }
    return regs;
}

std::vector<std::uint8_t> read_virtual_wiimote_bytes(
    bool register_space,
    std::uint32_t address,
    std::uint16_t size,
    bool extension_initialized) {
    if (size == 0) {
        return {};
    }
    std::vector<std::uint8_t> bytes;
    bytes.reserve(size);

    if (!register_space) {
        const auto eeprom = create_virtual_wiimote_eeprom();
        const std::uint64_t end = static_cast<std::uint64_t>(address) + size;
        if (end > eeprom.size()) {
            throw std::runtime_error("native Wiimote EEPROM read out of range");
        }
        bytes.insert(
            bytes.end(),
            eeprom.begin() + static_cast<std::ptrdiff_t>(address),
            eeprom.begin() + static_cast<std::ptrdiff_t>(end));
        return bytes;
    }

    const std::uint32_t page = address & kWiimoteRegisterPageMask;
    const std::uint32_t offset = address & 0xffu;
    const std::uint64_t end = static_cast<std::uint64_t>(offset) + size;
    if (page == kWiimoteExtensionRegisterBase) {
        if (!extension_initialized && offset >= 0xFAu) {
            throw std::runtime_error(
                "native Wiimote extension ID read before initialization");
        }
        const auto regs = create_virtual_nunchuk_registers(extension_initialized);
        if (end > regs.size()) {
            throw std::runtime_error(
                "native Wiimote extension register read out of range");
        }
        bytes.insert(
            bytes.end(),
            regs.begin() + static_cast<std::ptrdiff_t>(offset),
            regs.begin() + static_cast<std::ptrdiff_t>(end));
        return bytes;
    }
    if (page == kWiimoteSpeakerRegisterBase) {
        if (end > 0x0Au) {
            throw std::runtime_error(
                "native Wiimote speaker register read out of range");
        }
        bytes.resize(size, 0);
        return bytes;
    }
    if (page == kWiimoteIrRegisterBase) {
        if (end > 0x34u) {
            throw std::runtime_error(
                "native Wiimote IR register read out of range");
        }
        bytes.resize(size, 0);
        return bytes;
    }
    std::ostringstream message;
    message << "native Wiimote unsupported register read page 0x"
            << std::hex << page;
    throw std::runtime_error(message.str());
}

bool apply_virtual_wiimote_register_write(
    std::uint32_t address,
    std::span<const std::uint8_t> data,
    bool& extension_init_seen,
    bool& extension_initialized) {
    const std::uint32_t page = address & kWiimoteRegisterPageMask;
    const std::uint32_t offset = address & 0xffu;
    if (page == kWiimoteExtensionRegisterBase) {
        if (offset == 0xF0u && data.size() == 1u && data[0] == 0x55u) {
            extension_init_seen = true;
            extension_initialized = false;
            return true;
        }
        if (offset == 0xF0u && data.size() == 1u && data[0] == 0xAAu &&
            extension_initialized) {
            return true;
        }
        if (offset == 0xFBu && data.size() == 1u && data[0] == 0x00u &&
            extension_init_seen) {
            extension_initialized = true;
            return true;
        }
        if (offset == 0x40u && data.size() == 1u && data[0] == 0x00u) {
            extension_initialized = true;
            return true;
        }
        const std::uint32_t control_end =
            offset + static_cast<std::uint32_t>(data.size());
        if (data.size() >= 2u && extension_initialized && offset >= 0x40u &&
            control_end <= 0x50u) {
            return true;
        }
        if (offset == 0xFEu && data.size() == 1u && data[0] == 0x00u) {
            return true;
        }
    } else if (page == kWiimoteSpeakerRegisterBase) {
        if (offset == 0x09u && data.size() == 1u &&
            (data[0] == 0x00u || data[0] == 0x01u)) {
            return true;
        }
        if (offset == 0x01u && data.size() == 1u &&
            (data[0] == 0x01u || data[0] == 0x08u || data[0] == 0x80u)) {
            return true;
        }
        if (offset == 0x01u && data.size() == 7u) {
            return true;
        }
        if (offset == 0x08u && data.size() == 1u && data[0] == 0x01u) {
            return true;
        }
    } else if (page == kWiimoteIrRegisterBase) {
        if (offset == 0x30u && data.size() == 1u &&
            (data[0] == 0x01u || data[0] == 0x08u)) {
            return true;
        }
        if (offset == 0x00u && data.size() == 9u) {
            return true;
        }
        if (offset == 0x1Au && data.size() == 2u) {
            return true;
        }
        if (offset == 0x33u && data.size() == 1u &&
            (data[0] == 0x01u || data[0] == 0x03u || data[0] == 0x05u)) {
            return true;
        }
    }
    return false;
}

struct NativeHidControllerState {
    bool connected = false;
    DWORD slot = XUSER_MAX_COUNT;
    WORD buttons = 0;
    BYTE left_trigger = 0;
    BYTE right_trigger = 0;
    float left_x = 0.0f;
    float left_y = 0.0f;
    float right_x = 0.0f;
    float right_y = 0.0f;
};

bool native_hid_controller_has_input(
    const NativeHidControllerState& controller) {
    if (!controller.connected) {
        return false;
    }
    return controller.buttons != 0u || controller.left_trigger > 30u ||
           controller.right_trigger > 30u ||
           std::fabs(controller.left_x) > 0.001f ||
           std::fabs(controller.left_y) > 0.001f ||
           std::fabs(controller.right_x) > 0.001f ||
           std::fabs(controller.right_y) > 0.001f;
}

NativeHidControllerState poll_native_hid_controller() {
    NativeHidControllerState first_connected{};
    bool have_first_connected = false;
    const std::int16_t left_deadzone = xinput_left_deadzone();
    const std::int16_t pointer_deadzone = xinput_pointer_deadzone();
    for (DWORD slot = 0; slot < XUSER_MAX_COUNT; ++slot) {
        XINPUT_STATE state{};
        if (XInputGetState(slot, &state) != ERROR_SUCCESS) {
            continue;
        }
        NativeHidControllerState controller{};
        controller.connected = true;
        controller.slot = slot;
        controller.buttons = state.Gamepad.wButtons;
        controller.left_trigger = state.Gamepad.bLeftTrigger;
        controller.right_trigger = state.Gamepad.bRightTrigger;
        controller.left_x = galaxy::input::normalize_xinput_axis(
            state.Gamepad.sThumbLX, left_deadzone);
        controller.left_y = galaxy::input::normalize_xinput_axis(
            state.Gamepad.sThumbLY, left_deadzone);
        controller.right_x = galaxy::input::normalize_xinput_axis(
            state.Gamepad.sThumbRX, pointer_deadzone);
        controller.right_y = galaxy::input::normalize_xinput_axis(
            state.Gamepad.sThumbRY, pointer_deadzone);
        if (!have_first_connected) {
            first_connected = controller;
            have_first_connected = true;
        }
        if (native_hid_controller_has_input(controller)) {
            return controller;
        }
    }
    return have_first_connected ? first_connected : NativeHidControllerState{};
}

std::uint16_t wiimote_trace_button_bits(
    const galaxy::input::WiimoteButtons& buttons) {
    std::uint8_t byte0 = 0;
    std::uint8_t byte1 = 0;
    if (buttons.left) byte0 |= 0x01u;
    if (buttons.right) byte0 |= 0x02u;
    if (buttons.down) byte0 |= 0x04u;
    if (buttons.up) byte0 |= 0x08u;
    if (buttons.plus) byte0 |= 0x10u;
    if (buttons.two) byte1 |= 0x01u;
    if (buttons.one) byte1 |= 0x02u;
    if (buttons.b) byte1 |= 0x04u;
    if (buttons.a) byte1 |= 0x08u;
    if (buttons.minus) byte1 |= 0x10u;
    if (buttons.home) byte1 |= 0x80u;
    return static_cast<std::uint16_t>(
        (static_cast<std::uint16_t>(byte0) << 8u) | byte1);
}

bool foreground_process_window(HWND& window) {
    window = GetForegroundWindow();
    if (window == nullptr || !IsWindow(window) || !IsWindowVisible(window)) {
        return false;
    }
    DWORD pid = 0;
    GetWindowThreadProcessId(window, &pid);
    return pid == GetCurrentProcessId();
}

bool current_process_window_under_cursor(POINT& cursor, HWND& window) {
    if (!GetCursorPos(&cursor)) {
        window = nullptr;
        return false;
    }
    HWND hovered = WindowFromPoint(cursor);
    if (hovered == nullptr) {
        window = nullptr;
        return false;
    }
    if (HWND root = GetAncestor(hovered, GA_ROOT); root != nullptr) {
        hovered = root;
    }
    if (!IsWindow(hovered) || !IsWindowVisible(hovered)) {
        window = nullptr;
        return false;
    }
    DWORD pid = 0;
    GetWindowThreadProcessId(hovered, &pid);
    if (pid != GetCurrentProcessId()) {
        window = nullptr;
        return false;
    }
    window = hovered;
    return true;
}

bool current_process_runtime_window(HWND& window) {
    struct SearchState {
        DWORD pid = GetCurrentProcessId();
        HWND window = nullptr;
        HWND fallback_window = nullptr;
        std::int64_t fallback_area = 0;
    } state{};

    EnumWindows(
        [](HWND candidate, LPARAM user) -> BOOL {
            auto* search = reinterpret_cast<SearchState*>(user);
            if (candidate == nullptr || !IsWindow(candidate)) {
                return TRUE;
            }
            DWORD pid = 0;
            GetWindowThreadProcessId(candidate, &pid);
            if (pid != search->pid) {
                return TRUE;
            }
            if (!IsWindowVisible(candidate)) {
                return TRUE;
            }
            RECT client{};
            if (!GetClientRect(candidate, &client) ||
                client.right <= client.left ||
                client.bottom <= client.top) {
                return TRUE;
            }
            const std::int64_t area =
                static_cast<std::int64_t>(client.right - client.left) *
                static_cast<std::int64_t>(client.bottom - client.top);
            if (area > search->fallback_area) {
                search->fallback_window = candidate;
                search->fallback_area = area;
            }
            wchar_t class_name[64]{};
            if (GetClassNameW(candidate, class_name,
                              static_cast<int>(
                                  sizeof(class_name) /
                                  sizeof(class_name[0]))) == 0 ||
                lstrcmpW(class_name, L"NebulaRuntimeWndR") != 0) {
                return TRUE;
            }
            search->window = candidate;
            return FALSE;
        },
        reinterpret_cast<LPARAM>(&state));

    window = state.window != nullptr ? state.window : state.fallback_window;
    return window != nullptr;
}

struct NativeInputScriptOverlay {
    galaxy::input::WiimoteButtons buttons{};
    bool nunchuk_c = false;
    bool nunchuk_z = false;
    bool has_stick = false;
    float stick_x = 0.0f;
    float stick_y = 0.0f;
    bool has_pointer = false;
    float pointer_x = 0.0f;
    float pointer_y = 0.0f;
    bool shake = false;
    std::uint32_t trace_mask = 0;
    // Keep the long-form button script's contribution distinct from the
    // independent one-shot GALAXY_INPUT_AUTOPRESS_A* controls.  The live
    // Mario-control stop contract applies to this source specifically, and
    // its terminal guard must be able to prove that it contributed no A/B
    // bits at or after the published marker.
    std::uint32_t autopress_script_trace_mask = 0;
    bool autopress_script_stopped_at_mario_control = false;
    std::uint64_t autopress_script_stop_marker_vi = 0;
};

