bool GuestAddressSpace::dsp_native_service_mram_read_cb(
    void* user,
    std::uint32_t address,
    std::uint8_t* destination,
    std::uint32_t size) noexcept {
    if (user == nullptr || destination == nullptr || size == 0u) {
        return false;
    }
    auto& address_space = *static_cast<GuestAddressSpace*>(user);
    const std::byte* const source =
        address_space.pointer_or_null(address, size);
    if (source == nullptr) {
        return false;
    }
    std::memcpy(destination, source, size);
    return true;
}

bool GuestAddressSpace::dsp_native_service_mram_write_cb(
    void* user,
    std::uint32_t address,
    const std::uint8_t* source,
    std::uint32_t size) noexcept {
    if (user == nullptr || source == nullptr || size == 0u) {
        return false;
    }
    auto& address_space = *static_cast<GuestAddressSpace*>(user);
    std::byte* const destination =
        address_space.pointer_or_null(address, size);
    if (destination == nullptr) {
        return false;
    }
    std::memcpy(destination, source, size);
    // One transaction produces exactly one dirty range after every byte is
    // committed. The DSP worker never calls this notification path.
    address_space.notify_guest_write(address, size);
    return true;
}

bool GuestAddressSpace::dsp_native_service_aram_commit_write_cb(
    void* user,
    std::uint32_t address,
    const std::uint8_t* source,
    std::uint32_t size) noexcept {
    if (user == nullptr || source == nullptr || size == 0u) {
        return false;
    }
    auto& address_space = *static_cast<GuestAddressSpace*>(user);

    // Broadway ARAM DMA and a DSP mirror write to the same backing are two
    // independently progressing hardware jobs. Their overlap has no defined
    // byte-level winner in this runtime, so reject it instead of racing or
    // choosing a scheduler-dependent result. Non-overlapping jobs remain
    // ordered by this CPU-thread service point.
    if (address_space.aram_dma_active_) {
        const std::uint64_t dma_begin =
            UINT64_C(0x10000000) + address_space.aram_dma_aram_address_;
        const std::uint64_t remaining_blocks =
            address_space.aram_dma_total_blocks_ -
            address_space.aram_dma_completed_blocks_;
        const std::uint64_t dma_end =
            dma_begin + remaining_blocks * kAramDmaBlockBytes;
        const std::uint64_t write_begin = address & 0x1fffffffu;
        const std::uint64_t write_end = write_begin + size;
        if (write_begin < dma_end && write_end > dma_begin) {
            return false;
        }
    }

    std::byte* const destination =
        address_space.pointer_or_null(address, size);
    if (destination == nullptr) {
        return false;
    }
    std::memcpy(destination, source, size);
    // DSP->ARAM publication must invalidate renderer/shared consumers, but it
    // must not feed the CPU->mirror bitmap back into the next mailbox packet.
    address_space.notify_guest_write_renderer_only(address, size);
    return true;
}

